<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {ArrowLeft,ArrowUp,BookOpen,Check,ChevronRight,Database,FileText,FolderOpen,Layers,MessageSquare,MoreHorizontal,Plus,RefreshCw,Server,Settings2,Square,Trash2,Upload,X,Pencil,Search} from 'lucide-vue-next'
import {api,post,patch,remove,streamAnswer,upload} from './api'
import type {KB,Source,Doc,Job,Chunk,Citation,Conversation,Message,System,UploadResult} from './types'
const page=ref('knowledge'),kbs=ref<KB[]>([]),selected=ref<KB|null>(null),sources=ref<Source[]>([]),docs=ref<Doc[]>([]),jobs=ref<Job[]>([]),tab=ref('documents')
const error=ref(''),notice=ref(''),busy=ref(false),query=ref(''),system=ref<System|null>(null),ready=ref(false)
const modal=ref(''),editId=ref(''),form=ref({name:'',description:'',kind:'upload',path:'',interval:0})
const chunks=ref<Chunk[]>([]),drawerTitle=ref(''),citation=ref<Citation|null>(null),items=ref<{path:string;status:string;error:string}[]>([])
const uploadId=ref(''),uploadProgress=ref(0),uploading=ref(false),uploadResult=ref<UploadResult|null>(null),filesInput=ref<HTMLInputElement|null>(null),folderInput=ref<HTMLInputElement|null>(null)
const conversations=ref<Conversation[]>([]),activeConv=ref<Conversation|null>(null),messages=ref<Message[]>([]),chatKb=ref(''),question=ref(''),sending=ref(false),controller=ref<AbortController|null>(null),messageList=ref<HTMLElement|null>(null)
const deleteJobs=ref<Record<string,Job>>({})
const filteredDocs=computed(()=>docs.value.filter(d=>d.relative_path.toLowerCase().includes(query.value.toLowerCase())))
const labels:Record<string,string>={ready:'已索引',queued:'排队中',running:'处理中',failed:'失败',succeeded:'已完成',deleting:'删除中',cancelled:'已取消',streaming:'回答中',interrupted:'未完成',complete:'完成',added:'新增',modified:'更新',unchanged:'未变化',rejected:'拒绝'}
const kinds:Record<string,string>={index:'文档索引',sync:'目录同步',cleanup_document:'文档清理',rebuild:'索引重建',cleanup_index:'索引清理',delete_kb:'知识库删除'}
const date=(s:string|null)=>s?new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'尚未同步'
const location=(p:Citation['provenance'])=>p.pages?.length?`第 ${p.pages.join('、')} 页`:p.section?.join(' / ')||`原文位置 ${p.start}–${p.end}`
async function act(fn:()=>Promise<void>){error.value='';busy.value=true;try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function loadBases(){kbs.value=await api<KB[]>('/knowledge-bases');await Promise.all(kbs.value.filter(k=>k.status==='deleting').map(async k=>{const job=(await api<Job[]>(`/knowledge-bases/${k.id}/jobs`)).find(j=>j.kind==='delete_kb');if(job)deleteJobs.value[k.id]=job}));if(!chatKb.value)chatKb.value=kbs.value.find(k=>k.status==='active')?.id||''}
async function detail(){if(!selected.value)return;const id=selected.value.id;const [s,d,j]=await Promise.all([api<Source[]>(`/knowledge-bases/${id}/sources`),api<Doc[]>(`/knowledge-bases/${id}/documents`),api<Job[]>(`/knowledge-bases/${id}/jobs`)]);if(selected.value?.id===id){sources.value=s;docs.value=d;jobs.value=j}}
async function openKB(kb:KB){selected.value=kb;tab.value='documents';query.value='';await act(detail)}
function openForm(type:string,id=''){modal.value=type;editId.value=id;error.value='';const kb=kbs.value.find(x=>x.id===id),s=sources.value.find(x=>x.id===id);form.value={name:type==='kb'?kb?.name||'':s?.name||'',description:kb?.description||'',kind:s?.kind||'upload',path:s?.path||'',interval:(s?.interval_seconds||0)/60}}
async function save(){await act(async()=>{if(modal.value==='kb'){const data={name:form.value.name,description:form.value.description};if(editId.value){await patch(`/knowledge-bases/${editId.value}`,data);if(selected.value?.id===editId.value)selected.value={...selected.value,...data}}else await post('/knowledge-bases',data);await loadBases()}else if(selected.value){const data={name:form.value.name,kind:form.value.kind,path:form.value.path,interval_seconds:Math.round(form.value.interval*60)};if(editId.value)await patch(`/data-sources/${editId.value}`,data);else await post(`/knowledge-bases/${selected.value.id}/sources`,data);await detail()}modal.value=''})}
async function confirmDelete(){await act(async()=>{if(modal.value==='delete-kb'){await remove(`/knowledge-bases/${editId.value}`);selected.value=null;await loadBases()}else if(modal.value==='delete-doc'){await remove(`/documents/${editId.value}`);await detail()}else{await remove(`/conversations/${editId.value}`);if(activeConv.value?.id===editId.value){activeConv.value=null;messages.value=[]}await loadConversations()}modal.value=''})}
async function sync(id:string){await act(async()=>{await post(`/data-sources/${id}/sync`);notice.value='同步任务已加入队列';await detail();tab.value='jobs'})}
async function retry(id:string){await act(async()=>{await post(`/jobs/${id}/retry`);await detail()})}
async function preview(doc:Doc){await act(async()=>{chunks.value=await api<Chunk[]>(`/documents/${doc.id}/chunks`);drawerTitle.value=doc.name;citation.value=null;items.value=[]})}
async function showItems(job:Job){await act(async()=>{items.value=await api(`/jobs/${job.id}/items`);drawerTitle.value='文件处理明细';chunks.value=[];citation.value=null})}
async function viewCitation(source:Citation){await act(async()=>{citation.value=await api<Citation>(`/citations/${source.id}`);drawerTitle.value=source.name;chunks.value=[];items.value=[]})}
function chooseFiles(id:string,folder=false){uploadId.value=id;(folder?folderInput.value:filesInput.value)?.click()}
async function handleFiles(e:Event){const input=e.target as HTMLInputElement;await sendFiles(Array.from(input.files||[]));input.value=''}
async function sendFiles(files:File[]){if(!files.length||uploading.value)return;error.value='';uploading.value=true;uploadProgress.value=0;try{uploadResult.value=await upload(uploadId.value,files,n=>uploadProgress.value=n);await detail()}catch(e){error.value=(e as Error).message}finally{uploading.value=false}}
async function drop(e:DragEvent,id:string){uploadId.value=id;await sendFiles(Array.from(e.dataTransfer?.files||[]))}
async function rebuild(){await act(async()=>{if(selected.value){await post(`/knowledge-bases/${selected.value.id}/rebuild`);notice.value='已加入重建队列，完成前继续使用原索引';tab.value='jobs';await detail()}})}
async function loadConversations(){conversations.value=await api<Conversation[]>('/conversations')}
async function newConv(){await act(async()=>{activeConv.value=await post<Conversation>('/conversations');messages.value=[];await loadConversations()})}
async function openConv(conv:Conversation){if(sending.value)return;await act(async()=>{activeConv.value=conv;messages.value=await api<Message[]>(`/conversations/${conv.id}/messages`);await scroll()})}
async function renameConv(){if(!activeConv.value)return;const title=window.prompt('对话名称',activeConv.value.title);if(!title?.trim())return;await act(async()=>{await patch(`/conversations/${activeConv.value!.id}`,{title:title.slice(0,200)});activeConv.value!.title=title;await loadConversations()})}
async function scroll(){await nextTick();if(messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight}
async function send(retryMessage?:Message){if(sending.value||!chatKb.value)return;const content=retryMessage?messages.value.find(m=>m.role==='user'&&m.request_key===retryMessage.request_key)?.content:question.value.trim();if(!content)return;error.value='';if(!activeConv.value){try{activeConv.value=await post<Conversation>('/conversations')}catch(e){error.value=(e as Error).message;return}}
  const key=retryMessage?.request_key||crypto.randomUUID();if(!retryMessage)messages.value.push({id:key,role:'user',content,status:'complete',sources:[],meta:{},request_key:key,kb_id:chatKb.value})
  const assistant:Message=retryMessage||{id:key+'-assistant',role:'assistant',content:'',status:'streaming',sources:[],meta:{},request_key:key,kb_id:chatKb.value};assistant.content='';assistant.status='streaming';assistant.sources=[];assistant.meta={};if(!retryMessage)messages.value.push(assistant)
  question.value='';sending.value=true;controller.value=new AbortController();await scroll()
  try{await streamAnswer(`/conversations/${activeConv.value.id}/messages`,{kb_id:retryMessage?.kb_id||chatKb.value,content,request_key:key},controller.value.signal,(name,data)=>{const target=messages.value.find(m=>m.request_key===key&&m.role==='assistant')!;if(name==='delta')target.content+=data.content;if(name==='sources')target.sources=data;if(name==='meta'){target.meta=data;target.id=data.message_id}if(name==='done'){target.content=data.content;target.status='complete'}if(name==='error'){target.status='failed';target.meta.error=data.message;error.value=data.message}void scroll()})}
  catch(e){const target=messages.value.find(m=>m.request_key===key&&m.role==='assistant')!;target.status=(e as Error).name==='AbortError'?'interrupted':'failed';if((e as Error).name!=='AbortError')error.value=(e as Error).message}
  finally{sending.value=false;controller.value=null;await loadConversations().catch(()=>{});await scroll()}
}
let timer:ReturnType<typeof setInterval>
onMounted(()=>{void act(async()=>{await loadBases();await loadConversations();system.value=await api<System>('/system');ready.value=(await fetch('/api/health/ready')).ok});timer=setInterval(()=>{if(page.value==='knowledge'&&!busy.value){void loadBases().catch(()=>{});if(selected.value)void detail().catch(()=>{});}void fetch('/api/health/ready').then(r=>ready.value=r.ok).catch(()=>ready.value=false)},4000)})
onUnmounted(()=>{clearInterval(timer);controller.value?.abort()});watch(page,()=>{error.value='';notice.value='';drawerTitle.value=''})
</script>

<template>
<div class="shell">
  <aside class="sidebar"><div class="brand"><div class="brand-icon"><Layers :size="20"/></div><div><strong>知序</strong><small>KNOWLEDGE WORKSPACE</small></div></div><div class="nav-label">工作空间</div><button class="nav-button" :class="{active:page==='knowledge'}" @click="page='knowledge'" title="知识库"><BookOpen :size="18"/><span>知识库</span></button><button class="nav-button" :class="{active:page==='chat'}" @click="page='chat'" title="知识问答"><MessageSquare :size="18"/><span>知识问答</span></button><button class="nav-button" :class="{active:page==='settings'}" @click="page='settings'" title="运行配置"><Settings2 :size="18"/><span>运行配置</span></button><div class="sidebar-footer"><div><span class="dot" :class="{off:!ready}"/>{{ready?'服务运行正常':'依赖服务未就绪'}}</div><div class="mono">RAG WORKSPACE / 0.1</div></div></aside>
  <main class="main"><header class="topbar"><span>工作空间 / {{page==='knowledge'?'知识库':page==='chat'?'知识问答':'运行配置'}}</span><span class="mono">YOUR KNOWLEDGE, CONNECTED.</span></header>
    <div v-if="error" class="error" role="alert"><span>{{error}}</span><button @click="error=''" aria-label="关闭错误"><X :size="15"/></button></div><div v-if="notice" class="notice">{{notice}}<button @click="notice=''" style="float:right" aria-label="关闭提示"><X :size="14"/></button></div>
    <template v-if="page==='knowledge'">
      <template v-if="!selected"><div class="heading"><div><div class="eyebrow mono">01 / KNOWLEDGE LIBRARY</div><h1>让资料成为可用的知识</h1><p>接入文档，持续更新，在每一次回答中找到依据。</p></div><button class="button" @click="openForm('kb')"><Plus :size="16"/>新建知识库</button></div><div class="metric-strip"><div><strong>{{kbs.filter(k=>k.status==='active').length.toString().padStart(2,'0')}}</strong><small>知识库</small></div><div><strong>PDF / WORD / TXT</strong><small>支持扫描件 PDF 与本地 OCR</small></div></div><div v-if="!kbs.length" class="empty"><BookOpen :size="35"/><h2>从你的第一份资料开始</h2><p>创建知识库，再上传文件或连接服务器目录。</p><button class="button" @click="openForm('kb')">创建知识库</button></div><div v-else class="kb-grid"><article v-for="kb in kbs" :key="kb.id" class="kb-card" tabindex="0" @click="kb.status==='active'&&openKB(kb)" @keydown.enter="kb.status==='active'&&openKB(kb)"><div class="card-head"><div class="card-mark"><Database :size="21"/></div><button class="icon" @click.stop="openForm('kb',kb.id)" title="编辑知识库"><Pencil :size="15"/></button></div><h2>{{kb.name}}</h2><div v-if="deleteJobs[kb.id]?.status==='failed'" class="error">{{deleteJobs[kb.id].error}}<button class="button secondary" @click.stop="retry(deleteJobs[kb.id].id)" :disabled="busy">重试删除</button></div><p>{{kb.description||'添加你的资料，建立可以追溯来源的知识空间。'}}</p><div class="card-foot"><span>{{kb.status==='active'?'可用':'删除中'}}</span><span>查看知识库 <ChevronRight :size="12" style="vertical-align:middle"/></span></div></article></div></template>
      <template v-else><button class="back" @click="selected=null;drawerTitle=''"><ArrowLeft :size="14"/>全部知识库</button><div class="heading"><div><div class="eyebrow mono">KNOWLEDGE BASE</div><h1>{{selected.name}}</h1><p>{{selected.description||'管理数据源、文档和处理任务'}}</p></div><div class="actions"><button class="icon" @click="openForm('kb',selected.id)" title="编辑知识库"><Pencil :size="17"/></button><button class="icon" @click="modal='delete-kb';editId=selected.id" title="删除知识库"><Trash2 :size="17"/></button><button class="button" @click="chatKb=selected.id;page='chat'"><MessageSquare :size="15"/>开始问答</button></div></div><div class="tabs"><button v-for="t in [['documents','文档'],['sources','数据源'],['jobs','处理任务']]" :key="t[0]" class="tab" :class="{active:tab===t[0]}" @click="tab=t[0]">{{t[1]}} <small>{{t[0]==='documents'?docs.length:t[0]==='sources'?sources.length:jobs.length}}</small></button></div>
        <div v-if="tab==='documents'" class="panel"><div class="panel-top"><h3>知识文档</h3><div class="actions"><input class="search" v-model="query" placeholder="搜索名称或路径" aria-label="搜索文档"><button class="icon" @click="act(detail)" title="刷新"><RefreshCw :size="16"/></button><button class="button secondary" @click="tab='sources'"><Upload :size="15"/>接入资料</button></div></div><div v-if="!docs.length" class="empty" style="border:0"><FileText :size="30"/><h3>还没有文档</h3><p>添加数据源，开始构建知识库。</p><button class="button" @click="tab='sources';openForm('source')">添加数据源</button></div><div v-else class="table-wrap"><table><thead><tr><th>文档</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="doc in filteredDocs" :key="doc.id"><td><div class="file-cell"><FileText :size="20"/><div>{{doc.name}}<small>{{doc.relative_path}}</small><small v-if="doc.error" style="color:#a34430">{{doc.error}}</small></div></div></td><td><span class="badge" :class="doc.status">{{labels[doc.status]||doc.status}}</span></td><td><div class="actions"><button class="icon" @click="preview(doc)" :disabled="!doc.active_version_id" title="查看片段"><Search :size="16"/></button><button v-if="doc.name.toLowerCase().endsWith('.pdf')" class="icon" title="强制 OCR" @click="act(async()=>{await post(`/documents/${doc.id}/reprocess?force_ocr=true`);await detail();tab='jobs'})"><RefreshCw :size="15"/></button><button class="icon" @click="modal='delete-doc';editId=doc.id" title="删除文档"><Trash2 :size="15"/></button></div></td></tr></tbody></table><p v-if="!filteredDocs.length" class="muted" style="padding:20px">没有匹配文档。</p></div></div>
        <template v-if="tab==='sources'"><div class="heading"><div><h2>数据源</h2><p>上传资料，或同步只读挂载的服务器目录。</p></div><button class="button" @click="openForm('source')"><Plus :size="15"/>添加数据源</button></div><div v-if="!sources.length" class="empty"><FolderOpen :size="32"/><h3>选择资料从哪里来</h3><p>上传适合手动导入；服务器目录支持定时增量同步。</p></div><div class="source-grid"><section v-for="source in sources" :key="source.id" class="source-card"><header><div class="actions"><component :is="source.kind==='upload'?Upload:Server" :size="20"/><h3 style="margin:0">{{source.name}}</h3><span class="badge">{{source.kind==='upload'?'本地上传':'服务器目录'}}</span></div><div class="actions"><button class="icon" title="编辑数据源" @click="openForm('source',source.id)"><Pencil :size="15"/></button><button v-if="source.kind==='directory'" class="button secondary" @click="sync(source.id)"><RefreshCw :size="14"/>立即同步</button></div></header><template v-if="source.kind==='directory'"><p class="mono" style="margin:18px 0 8px">{{source.path}}</p><small>{{source.interval_seconds?`每 ${source.interval_seconds/60} 分钟同步`:'仅手动同步'}} · 最近完整同步 {{date(source.last_scan_at)}}</small></template><div v-else class="upload-zone" @dragover.prevent @drop.prevent="drop($event,source.id)"><Upload :size="25"/><h3>把资料放到这里</h3><p>拖入文件，或选择文件 / 文件夹。支持 PDF、DOC、DOCX、TXT。</p><div class="actions" style="justify-content:center"><button class="button secondary" @click="chooseFiles(source.id)" :disabled="uploading"><FileText :size="14"/>选择文件</button><button class="button secondary" @click="chooseFiles(source.id,true)" :disabled="uploading"><FolderOpen :size="14"/>选择文件夹</button></div><template v-if="uploadId===source.id&&uploading"><div class="progress"><span :style="{width:uploadProgress+'%'}"/></div><small>上传 {{uploadProgress}}% · 索引在后台处理</small></template><div v-if="uploadId===source.id&&uploadResult" class="upload-results"><div v-for="file in uploadResult.files" :key="file.path">{{file.path}} · <span :style="{color:file.status==='rejected'?'#a34430':'#397347'}">{{labels[file.status]||file.status}}{{file.error?'：'+file.error:''}}</span></div></div></div></section></div></template>
        <div v-if="tab==='jobs'" class="panel"><div class="panel-top"><h3>后台处理任务</h3><button class="button secondary" @click="rebuild" :disabled="busy"><RefreshCw :size="14"/>重建向量索引</button></div><div v-if="!jobs.length" class="empty" style="border:0"><h3>暂无处理任务</h3><p>导入资料后，在这里查看进度。</p></div><div v-else class="table-wrap"><table><thead><tr><th>任务 / 时间</th><th>进度</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{kinds[job.kind]||job.kind}}<small>{{date(job.created_at)}}</small><small v-if="job.error" style="color:#a34430;max-width:400px">{{job.error}}</small><small v-if="Object.keys(job.counts).length">{{Object.entries(job.counts).map(([k,v])=>`${labels[k]||k} ${v}`).join(' · ')}}</small></td><td style="min-width:140px"><small>{{job.progress}}% · {{job.phase}}</small><div class="progress"><span :style="{width:job.progress+'%'}"/></div></td><td><span class="badge" :class="job.status">{{labels[job.status]||job.status}}</span></td><td><button v-if="job.status==='failed'" class="icon" @click="retry(job.id)" title="重试任务"><RefreshCw :size="15"/></button><button v-if="job.kind==='sync'" class="icon" @click="showItems(job)" title="文件明细"><MoreHorizontal :size="18"/></button></td></tr></tbody></table></div></div>
      </template>
    </template>
    <template v-if="page==='chat'"><div class="heading"><div><div class="eyebrow mono">02 / GROUNDED CONVERSATIONS</div><h1>向你的知识提问</h1></div><span class="mono muted">DEEPSEEK + QWEN</span></div><div class="chat-layout"><aside class="conversations"><button class="button secondary" style="width:100%" @click="newConv" :disabled="sending"><Plus :size="15"/>新建对话</button><div v-for="conv in conversations" :key="conv.id" class="conversation" :class="{selected:activeConv?.id===conv.id}"><button class="title" @click="openConv(conv)"><MessageSquare :size="14"/><span>{{conv.title}}</span></button><button class="icon" title="删除对话" :disabled="sending" @click="modal='delete-conv';editId=conv.id"><X :size="12"/></button></div></aside><section class="chat-main"><div class="chat-toolbar"><button class="muted" @click="renameConv" :disabled="sending" title="重命名对话">{{activeConv?.title||'新对话'}} <Pencil v-if="activeConv" :size="12" style="vertical-align:middle"/></button><select v-model="chatKb" aria-label="选择问答知识库" :disabled="sending"><option value="">选择知识库</option><option v-for="kb in kbs.filter(k=>k.status==='active')" :value="kb.id" :key="kb.id">{{kb.name}}</option></select></div><div class="message-list" ref="messageList"><div v-if="!messages.length" class="welcome"><div class="card-mark"><Layers :size="26"/></div><h2>答案，来自你的资料</h2><p>选择知识库，提出一个问题。<br>支持连续追问，每个回答都可以查看来源依据。</p></div><article v-for="message in messages" :key="message.request_key+message.role" class="message" :class="message.role"><div class="message-label"><component :is="message.role==='user'?MessageSquare:Layers" :size="13"/>{{message.role==='user'?'你':'知序'}}<span v-if="message.status!=='complete'" class="badge" :class="message.status">{{labels[message.status]||message.status}}</span></div><div class="message-body">{{message.content}}<span v-if="message.status==='streaming'" class="typing"/></div><div v-if="message.meta.degraded?.length" class="notice" style="margin-top:12px">{{message.meta.degraded.join('；')}}</div><div v-if="message.meta.error" class="error">{{message.meta.error}}</div><div class="citations"><button v-for="source in message.sources" :key="source.id" class="citation" @click="viewCitation(source)"><FileText :size="12"/>[{{source.number}}] {{source.name}}</button></div><button v-if="['failed','interrupted'].includes(message.status)" class="button secondary" style="margin-top:10px" @click="send(message)" :disabled="sending"><RefreshCw :size="13"/>重试回答</button></article></div><form class="composer" @submit.prevent="send()"><div class="composer-box"><textarea v-model="question" :disabled="sending" placeholder="输入问题，Enter 发送，Shift + Enter 换行" aria-label="问题" @keydown.enter.exact.prevent="send()"/><button v-if="sending" type="button" class="button" @click="controller?.abort()" title="停止回答"><Square :size="17"/></button><button v-else class="button" :disabled="!question.trim()||!chatKb" title="发送问题"><ArrowUp :size="18"/></button></div><small>基于知识库资料回答，请结合来源核查重要信息。</small></form></section></div></template>
    <template v-if="page==='settings'"><div class="heading"><div><div class="eyebrow mono">03 / SYSTEM CONFIGURATION</div><h1>运行配置</h1><p>连接通过服务器环境变量配置，密钥仅保留在后端。</p></div></div><div class="settings-grid"><section v-for="(model,key) in system?.models" :key="key" class="settings-card"><component :is="key==='deepseek'?MessageSquare:key==='embedding'?Database:Layers" :size="23"/><h3>{{key==='deepseek'?'回答生成':key==='embedding'?'文本向量化':'结果重排序'}}</h3><p class="mono">{{model.model||'未配置模型 ID'}}</p><span class="badge" :class="{failed:!model.configured}">{{model.configured?'已配置':'待配置'}}</span></section></div><section class="source-card" style="margin-top:24px"><h3>文档处理</h3><p>本地 OCR · DOC / DOCX 转换 · 结构优先切块</p><p>目标 {{system?.chunking.target}} / 最大 {{system?.chunking.max}} / 重叠 {{system?.chunking.overlap}} · 计数器 {{system?.chunking.counter}}</p><p>服务器目录根：<code>{{system?.sources_root}}</code><br>最大单文件：{{Math.round((system?.max_upload_bytes||0)/1024/1024)}} MB</p></section><div class="notice" style="margin-top:24px">本地 OCR 在服务器识别扫描页。相关文本会发送至配置的外部 Embedding、Rerank 和生成模型服务。</div></template>
  </main>
  <input ref="filesInput" class="hidden" type="file" multiple accept=".pdf,.doc,.docx,.txt" @change="handleFiles"><input ref="folderInput" class="hidden" type="file" multiple webkitdirectory @change="handleFiles">
  <div v-if="modal" class="overlay" @click.self="modal=''" @keydown.esc="modal=''">
    <form v-if="['kb','source'].includes(modal)" class="modal" @submit.prevent="save"><header><h2>{{editId?'编辑':'新建'}}{{modal==='kb'?'知识库':'数据源'}}</h2><button type="button" class="icon" @click="modal=''" aria-label="关闭"><X :size="18"/></button></header><div v-if="error" class="error" role="alert">{{error}}</div><label class="field"><span>名称</span><input v-model="form.name" required maxlength="200" autofocus placeholder="例如：产品手册"></label><label v-if="modal==='kb'" class="field"><span>描述</span><textarea v-model="form.description" rows="3" placeholder="这个知识库包含哪些资料？"/></label><template v-else><label class="field"><span>接入方式</span><select v-model="form.kind" :disabled="!!editId"><option value="upload">文件 / 文件夹上传</option><option value="directory">服务器目录</option></select></label><template v-if="form.kind==='directory'"><label class="field"><span>容器内目录路径</span><input v-model="form.path" :disabled="!!editId" required :placeholder="system?.sources_root+'/manuals'"></label><p class="muted" style="font-size:11px">请先将目录只读挂载到 {{system?.sources_root}} 内。根路径创建后不可修改。</p><label class="field"><span>自动同步间隔（分钟，0 为仅手动同步）</span><input type="number" min="0" max="525600" v-model.number="form.interval"></label></template></template><footer><button type="button" class="button secondary" @click="modal=''">取消</button><button class="button" :disabled="busy"><Check :size="15"/>保存</button></footer></form>
    <section v-else class="modal"><header><h2>确认删除</h2><button class="icon" @click="modal=''" aria-label="关闭"><X :size="18"/></button></header><p class="muted">{{modal==='delete-kb'?'知识库中的原文件、文本块和索引将被清理。':modal==='delete-doc'?'文档将退出检索。服务器文件仍存在时，下次同步会重新接入。':'会话与消息将被删除。'}}</p><footer><button class="button secondary" @click="modal=''">取消</button><button class="button danger" @click="confirmDelete" :disabled="busy">确认删除</button></footer></section>
  </div>
  <aside v-if="drawerTitle" class="drawer"><header><div><div class="eyebrow mono">SOURCE EXPLORER</div><h2>{{drawerTitle}}</h2></div><button class="icon" @click="drawerTitle=''" aria-label="关闭来源"><X :size="20"/></button></header><template v-if="citation"><p class="muted">{{location(citation.provenance)}}</p><div v-if="citation.document_available===false" class="notice">原文档已删除，以下为回答时保留的引用快照。</div><div class="excerpt">{{citation.original}}</div></template><template v-else-if="chunks.length"><article v-for="(chunk,index) in chunks" :key="chunk.id" class="chunk"><span class="mono muted">CHUNK {{(index+1).toString().padStart(3,'0')}}</span><small>{{location(chunk.provenance)}} · 预算计数 {{chunk.provenance.budget_count}}</small><div class="excerpt">{{chunk.original}}</div></article></template><template v-else-if="items.length"><article v-for="item in items" :key="item.path" class="chunk"><h3>{{item.path}}</h3><span class="badge" :class="item.status">{{labels[item.status]||item.status}}</span><p v-if="item.error" class="muted" style="margin-top:12px">{{item.error}}</p></article></template><p v-else class="muted">暂无可显示的片段或处理明细。</p></aside>
</div>
</template>
